test('overdueInvoices sorts by daysOverdue descending', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;
  const issued3 = issueInvoice(inv3, ['INV-2026-0001', 'INV-2026-0002']).value;

  // NET30: inv1 due 2026-11-09, inv2 due 2026-10-31, inv3 due 2026-11-04
  const r = overdueInvoices([issued1, issued2, issued3], '2026-11-15');

  assert.equal(r.length, 3);
  // inv2 has most days overdue
  assert.equal(r[0].number, 'INV-2026-0002');
  assert.equal(r[0].daysOverdue, 15); // 2026-11-15 - 2026-10-31
  // inv3 is second
  assert.equal(r[1].number, 'INV-2026-0003');
  assert.equal(r[1].daysOverdue, 11); // 2026-11-15 - 2026-11-04
  // inv1 is third (least overdue)
  assert.equal(r[2].number, 'INV-2026-0001');
  assert.equal(r[2].daysOverdue, 6); // 2026-11-15 - 2026-11-09
});

