    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // C-001 gold tier: 9771
  // Due 2026-11-06
  // Fee on 2026-11-16 (10 days overdue) = 9771 * (10 * 0.04 / 100) = 9771 * 0.004 = 39.084 -> 39
  const fee = lateFee(issued, '2026-11-16');

  assert.equal(fee, 39);
});

