test('lateFee with month boundary', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // C-001 gold tier: 9771
  // NET30 from 2026-09-01 = due 2026-10-01
  // Fee on 2026-10-31 (30 days overdue) = 9771 * (30 * 0.04 / 100) = 9771 * 0.12 = 1172.52 -> 1173
  const fee = lateFee(issued, '2026-10-31');

  assert.equal(fee, 1173);
});

test('lateFee with year boundary', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // C-001 gold tier: 9771
  // NET30 from 2025-12-01 = due 2025-12-31
  // Fee on 2026-01-31 (31 days overdue) = 9771 * (31 * 0.04 / 100) = 9771 * 0.124 = 1211.604 -> 1212
  const fee = lateFee(issued, '2026-01-31');

  assert.equal(fee, 1212);
});

test('lateFee rounding uses banker\'s rounding', () => {
  const invoice = {
    status: 'issued',
    dueDate: '2026-11-06',
    lines: [{ qty: 1, unitPrice: 12500, vatRate: 0 }],
  };

  // Due = 12500
  // 1 day overdue: 12500 * 0.04% = 5.0 -> 5
  // 3 days overdue: 12500 * 0.12% = 15.0 -> 15
  assert.equal(lateFee(invoice, '2026-11-07'), 5);
  assert.equal(lateFee(invoice, '2026-11-09'), 15);
});

