  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // C-002 standard tier: 85000 + 17850 = 102850
  // NET30 from 2026-10-01 = due 2026-10-31
  // Fee on 2026-12-31 (61 days overdue) = 102850 * (61 * 0.04 / 100) = 102850 * 0.0244 = 2509.54 -> 2510
  const fee = lateFee(issued, '2026-12-31');

  assert.equal(fee, 2510);
});

